"""The port against goldens generated by the OLD code (``python -m projectzero.ops.parity_ranking goldens``):
legacy text-building quirks (absent vs null, list repr, numbers, unicode) and the feedback ledger (no file, empty,
not a dict, positive, negative, mixed with Manager outcomes and round-half-away)."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pytest

from projectzero.ops.parity_ranking import diff, run_new

GOLDEN = json.loads(
    (Path(__file__).resolve().parents[1] / "fixtures" / "golden_v1" / "oracle_quirks_feedback.json").read_text(
        encoding="utf-8"
    )
)
NEW = run_new(GOLDEN["candidates"], GOLDEN["ledgers"], GOLDEN["last_run"])


def test_provenance_is_the_clean_old_revision() -> None:
    assert GOLDEN["provenance"]["old_revision"] == "6c739b9cb6ca2517b845e381d39a36c50eccc59e"
    assert GOLDEN["provenance"]["old_domain_dirty"] is False


def test_same_candidate_keys() -> None:
    assert NEW.keys() == GOLDEN["expected"].keys()


@pytest.mark.parametrize("key", sorted(GOLDEN["expected"]))
def test_candidate_matches_the_old_code(key: str) -> None:
    assert diff(GOLDEN["expected"][key], NEW[key]) == []


def test_absent_vs_null_differs_in_text_but_not_in_todays_scores() -> None:
    """The text builder keeps the difference ('None' reaches the rules); today's rules happen not to react to it."""
    from projectzero.dealflow.ranking.pytext import joined

    assert joined({"a": None}, ("a",)) == "None" and joined({}, ("a",)) == ""
    absent, null = GOLDEN["expected"]["0:absent-fields"], GOLDEN["expected"]["1:null-fields"]
    assert absent["attention_v2"]["final"] == null["attention_v2"]["final"]


def test_list_repr_versus_spaced_join_is_observable() -> None:
    """``why = ["Series", "B"]``: score_v2 reads "['series', 'b']" (no Series penalty), entity_type reads "Series B"."""
    got = GOLDEN["expected"]["20:repr-vs-spaces"]["attention_v2"]
    assert all(label != "Series A or later" for label, _ in got["applied"])
    assert got["entity"]["type"] == "VENTURE" and got["entity"]["reason"] == "explicit company/startup evidence"


def test_the_ledgers_produce_positive_negative_and_neutral_adjustments() -> None:
    multi: dict[str, Any] = GOLDEN["expected"]["18:multi-source"]["feedback"]["mixed"]
    by_source = {s["source_id"]: s["adjustment"] for s in multi["sources"]}
    assert by_source["src-pos"] > 0 and by_source["src-neg"] < 0 and by_source["src-half"] == 1  # 0.5 rounds away
    assert all(GOLDEN["expected"][k]["feedback"]["no_file"]["adjustment"] == 0 for k in GOLDEN["expected"])


# ── review 006 implementation: survivors are checked against the import plan, never inferred from absence ──────

from projectzero.ops.parity_ranking import verify_survivors  # noqa: E402

ALIASES = [
    {"namespace": "candidate", "alias_id": "a", "candidate_id": "a", "reason": "own_id"},
    {"namespace": "candidate", "alias_id": "b", "candidate_id": "a", "reason": "merge"},
    {"namespace": "candidate", "alias_id": "c", "candidate_id": "c", "reason": "own_id"},
    {"namespace": "scout_intake", "alias_id": "si-1", "candidate_id": "s1", "reason": "legacy_import"},
]


def test_complete_survivor_set_passes() -> None:
    assert verify_survivors({"a", "c", "s1"}, {"a", "c", "s1"}, ALIASES, {"a", "b", "c"}) == []


def test_one_omitted_survivor_fails() -> None:
    problems = verify_survivors({"a", "c", "s1"}, {"a", "s1"}, ALIASES, {"a", "b", "c"})
    assert "missing survivor c" in problems
    assert any(p.startswith("source c not returned but its alias is not a merge") for p in problems)


def test_an_empty_list_fails_instead_of_counting_everything_as_merged() -> None:
    problems = verify_survivors({"a", "c", "s1"}, set(), ALIASES, {"a", "b", "c"})
    assert len([p for p in problems if p.startswith("missing survivor")]) == 3


def test_extra_candidates_and_merges_into_missing_survivors_fail() -> None:
    problems = verify_survivors({"a", "c"}, {"c", "zz"}, ALIASES, {"a", "b", "c"})
    assert "unexpected candidate zz" in problems
    assert "source b merged into a, which the list did not return" in problems
